```python
def fprop(self, inputs, stochastic=True):
    if stochastic:
        batch_mean = np.mean(inputs, axis=0)
        self.batch_mean = batch_mean
        batch_var = np.var(inputs, axis=0)
        self.batch_var = batch_var
    else:
        batch_mean = self.batch_mean
        batch_var = self.batch_var
    x_hat = (inputs - batch_mean) / np.sqrt(batch_var + self.epsilon)
    self.x_hat = x_hat
    outputs = self.gamma * x_hat + self.beta
    return outputs
```

