class SELULayer(Layer):
    """Layer implementing a scaled exponential linear (SELU) activation."""
    #α01 ≈ 1.6733 and λ01 ≈ 1.0507
    def __init__(self):
        self.alpha = 1.6732632423543772848170429916717
        self.lamda = 1.0507009873554804934193349852946
        self.elu = ELULayer(self.alpha)
    def fprop(self, inputs):
        """Forward propagates activations through the layer transformation.

        For inputs `x` and outputs `y` this corresponds to `y = lamda * x`
        for positive `x` and `y = lamda * alpha * (exp(x) - 1)` otherwise.
        """
        return self.lamda * self.elu.fprop(inputs)

    def bprop(self, inputs, outputs, grads_wrt_outputs):
        """Back propagates gradients through a layer.

        Given gradients with respect to the outputs of the layer calculates the
        gradients with respect to the layer inputs.
        """
        return self.lamda * self.elu.bprop(
            inputs, outputs / self.lamda, grads_wrt_outputs)

